<?php require __DIR__ . '/../includes/config.php';require_admin();if(isset($_GET['delete'])){$pdo->prepare('DELETE FROM products WHERE id=?')->execute([(int)$_GET['delete']]);flash('success','Product deleted.');redirect('admin/products.php');}$products=$pdo->query('SELECT p.*,c.name category FROM products p LEFT JOIN categories c ON c.id=p.category_id ORDER BY p.created_at DESC')->fetchAll();$pageTitle='Manage products';require __DIR__ . '/../includes/header.php'; ?><div class="admin-shell"><div class="row g-0"><aside class="col-lg-2 admin-side"><div class="eyebrow">Control room</div><h2 class="h4 mt-2">Nexa admin</h2><nav class="mt-4"><a href="index.php">Overview</a><a class="active" href="products.php">Products</a><a href="categories.php">Categories</a><a href="orders.php">Orders</a><a href="users.php">Users</a><a href="../index.php">View store</a></nav></aside><section class="col-lg-10 p-4 p-lg-5"><div class="d-flex justify-content-between mb-4"><h1 class="h2">Products</h1><a class="btn btn-accent" href="create_product.php">+ Create product</a></div><div class="panel table-responsive"><table class="table"><thead><tr><th>Product</th><th>Category</th><th>Price</th><th>Stock</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($products as $product): ?><tr><td><img src="<?= e($product['image']) ?>" width="48" height="48" class="me-2" style="object-fit:cover" alt=""><?= e($product['name']) ?></td><td><?= e($product['category']) ?></td><td>$<?= number_format($product['price'],2) ?></td><td><?= $product['stock'] ?></td><td><?= e($product['status']) ?></td><td class="text-end"><a href="product_edit.php?id=<?= $product['id'] ?>">Edit</a> · <a class="text-danger" href="?delete=<?= $product['id'] ?>" onclick="return confirm('Delete this product?')">Delete</a></td></tr><?php endforeach; ?></tbody></table></div></section></div></div><?php require __DIR__ . '/../includes/footer.php'; ?>